config.script:
// Registrador de notas (épico #2268) — acorda a cada pagamento; a tabela de regras decide se
// nasce a nota PREVISTA (saldo de quem pagou). O financeiro relê valores e pagador no vendas e
// reconcilia a venda inteira: aqui só se decide e se chama a rota certa. Nunca devolve CPF.
var et = event.event_type || '';
var sub = event.subject || {};
var vendaId = sub.venda_id;
var pagId = sub.pagamento_id;
var agente = String(context.agente || 'registrador_notas').slice(0, 80);
var agrupar = config.agrupar_por || 'dia';

function fim(saida, extra) {
  var r = { saida: saida, evento: et };
  extra = extra || {};
  for (var k in extra) r[k] = extra[k];
  result(r);
  return r;
}
function corpo(r) { return (r && r.body) || {}; }

if (!vendaId || !pagId) return fim('ignorado', { motivo: 'evento sem venda ou pagamento' });

if (et === 'vendas.pagamento_estornado' || et === 'vendas.pagamento_estornado_direto') {
  var e = call('pagamento_estornado', { pagamento_id: pagId, venda_id: vendaId, agente: agente, regra: 'estorno', agrupar_por: agrupar });
  return fim('estorno', { ok: e.ok, status: e.status_code, resultado: corpo(e).resultado });
}
if (et === 'vendas.pagamento_atualizado') {
  var a = call('pagamento_atualizado', { pagamento_id: pagId, venda_id: vendaId, agente: agente, regra: 'troca de pagador', agrupar_por: agrupar });
  return fim('pagador_trocado', { ok: a.ok, status: a.status_code, resultado: corpo(a).resultado });
}

// pagamento recebido / parcela paga → monta a entrada da tabela
var pg = call('listar_pagadores', { venda_id: vendaId });
if (!pg.ok) return fim('erro', { etapa: 'pagadores', status: pg.status_code });
var pags = corpo(pg).pagadores || [];
var meu = null;
for (var i = 0; i < pags.length; i++) if (String(pags[i].pagamento_id) === String(pagId)) meu = pags[i];
if (!meu) return fim('ignorado', { motivo: 'pagamento fora da venda' });

function chave(p) {
  return p.pagador_tipo + ':' + (p.pagador_documento || (p.pagador_tipo === 'paciente' ? 'paciente' : (p.pagador_nome || '')));
}
var formas = [], valor = 0, total = 0;
for (var j = 0; j < pags.length; j++) {
  var v = Number(pags[j].valor_rateio || 0);
  total += v;
  if (chave(pags[j]) === chave(meu)) {
    valor += v;
    if (formas.indexOf(pags[j].forma_pagamento) < 0) formas.push(pags[j].forma_pagamento);
  }
}

var vr = call('buscar_venda', { venda_id: vendaId });
var venda = vr.ok ? corpo(vr) : {};
var procs = [];
(venda.itens || []).forEach(function (it) { if (it.procedimento_id && procs.indexOf(it.procedimento_id) < 0) procs.push(it.procedimento_id); });

var entrada = {
  formas: formas,
  valor: Math.round(valor * 100) / 100,
  profissional: venda.profissional_id ? [venda.profissional_id] : [],
  procedimento: procs,
  quem_pagou: meu.pagador_tipo || 'paciente',
  tem_cpf: !!meu.pagador_documento,
  tipo_venda: (Number(venda.valor_convenio || 0) > 0 || venda.convenio_codigo) ? 'convenio' : 'particular',
  cobre_venda: vr.ok ? total + 0.005 >= Number(venda.valor_total || 0) : false
};

var d = regras.avaliar(config.regras_registro, entrada, 'regras_registro');
if (d.saida !== 'gerar_prevista') return fim(d.saida || 'sem_regra', { regra: d.linha });

var r = call('registrar_prevista', {
  venda_id: vendaId, pagamento_id: pagId, regra: 'linha ' + d.linha, agente: agente, agrupar_por: agrupar
});
return fim('gerar_prevista', { regra: d.linha, ok: r.ok, status: r.status_code, resultado: corpo(r).resultado });

// Confirmador de notas (épico #2268) — item executado/cancelado forma a nota (o financeiro reconcilia a venda
// inteira); no horário de fechamento, cada nota cujo período acabou vai para Revisar ou é transmitida, pela
// tabela de regras. Pendência aberta o financeiro manda sempre para a revisão. Nunca devolve CPF.
var et = event.event_type || '';
var agente = String(context.agente || 'confirmador_notas').slice(0, 80);
var agrupar = config.agrupar_por || 'dia';

function fim(saida, extra) {
  var r = { saida: saida, evento: et || event.origem || '' };
  extra = extra || {};
  for (var k in extra) r[k] = extra[k];
  result(r);
  return r;
}
function corpo(r) { return (r && r.body) || {}; }
function unicos(lista) {
  var out = [];
  lista.forEach(function (x) { if (x && out.indexOf(x) < 0) out.push(x); });
  return out;
}

// 1) item executado / cancelado → nota em formação (dia ou mês, por venda + pagador)
if (et === 'vendas.item_executado' || et === 'vendas.item_cancelado') {
  var sub = event.subject || {};
  if (!sub.venda_id) return fim('ignorado', { motivo: 'evento sem venda' });
  var cancelado = et === 'vendas.item_cancelado';
  var r = call('item_executado', {
    venda_id: sub.venda_id, venda_item_id: sub.venda_item_id, agrupar_por: agrupar, agente: agente,
    regra: cancelado ? 'item cancelado' : 'item executado',
    evento: cancelado ? 'item_cancelado' : 'item_executado'
  });
  var b = corpo(r);
  return fim(et === 'vendas.item_cancelado' ? 'item_cancelado' : 'item_executado', {
    ok: r.ok, status: r.status_code, resultado: b.resultado, notas_em_formacao: (b.notas_formadas || []).length
  });
}
if (event.origem !== 'cron') return fim('ignorado', { motivo: 'gatilho desconhecido' });

// 2) fechamento por horário
var lista = call('notas_para_fechar', { agrupar_por: agrupar });
if (!lista.ok) return fim('erro', { etapa: 'notas_para_fechar', status: lista.status_code });
var notas = corpo(lista).notas || [];
var cacheVenda = {}, cachePagadores = {};
var conta = { notas: notas.length, revisar: 0, transmitir: 0, forcadas_revisao: 0, erros: 0 };

function venda(id) {
  if (!id) return {};
  if (cacheVenda[id] === undefined) { var v = call('buscar_venda', { venda_id: id }); cacheVenda[id] = v.ok ? corpo(v) : {}; }
  return cacheVenda[id];
}
function pagadoresDaVenda(id) {
  if (!id) return 0;
  if (cachePagadores[id] === undefined) {
    var s = call('situacao_venda', { venda_id: id });
    var chaves = (corpo(s).notas || [])
      .filter(function (n) { return ['dispensada', 'cancelada'].indexOf(n.status) < 0; })
      .map(function (n) { return (n.tomador_nome || '') + '|' + (n.tem_documento ? 1 : 0); });
    cachePagadores[id] = unicos(chaves).length;
  }
  return cachePagadores[id];
}

notas.forEach(function (n) {
  var v = venda(n.venda_id);
  var itensNota = (n.itens || []).filter(function (i) { return i.ativo !== false; }).map(function (i) { return i.venda_item_id; });
  var itensVenda = (v.itens || []).filter(function (i) { return itensNota.indexOf(i.id) >= 0; });
  // `entradas` vem pronta do financeiro (v0.0.40); sem ela (Vendas falhou para a venda), calcula aqui.
  var e = n.entradas || null;
  var entrada = {
    valor: e && e.valor != null ? Number(e.valor) : Number(n.valor_servico || 0),
    formas: e && e.formas_pagamento ? e.formas_pagamento
      : unicos((n.pagamentos || []).filter(function (p) { return p.ativo !== false; }).map(function (p) { return p.forma_pagamento; })),
    profissional: unicos([v.profissional_id].concat(itensVenda.map(function (i) { return i.profissional_executor_id; }))),
    procedimento: unicos(itensVenda.map(function (i) { return i.procedimento_id; })),
    tem_cpf: !!n.tem_documento,
    tem_pendencia: e ? !!e.tem_pendencia : !!n.acao_pendente,
    mais_de_um_pagador: e ? !!e.mais_de_um_pagador : pagadoresDaVenda(n.venda_id) > 1,
    pago_em_mes_diferente: e ? !!e.pago_em_mes_diferente : false,
    atendimento_cancelado: e ? !!e.atendimento_cancelado : false
  };
  var d = regras.avaliar(config.regras_confirmacao, entrada, 'regras_confirmacao');
  var decisao = d.saida === 'transmitir' ? 'transmitir' : 'revisar';
  var f = call('fechar_nota', { nota_id: n.id, decisao: decisao, regra: 'linha ' + d.linha, agente: agente });
  if (!f.ok) { conta.erros++; return; }
  var fb = corpo(f);
  if (fb.forcada_revisao) conta.forcadas_revisao++;
  conta[fb.forcada_revisao ? 'revisar' : decisao]++;
});
return fim('fechamento', conta);

// Vigia de notas (épico #2268 + aviso na hora #2331) — avisa a equipe, sem dado de paciente (só quantidade, valor e o
// motivo do erro):
//  - NA HORA: o financeiro anuncia a nota recusada pelo governo (financeiro.nota_rejeitada) ou a transmissão parada que
//    não volta sozinha (financeiro.nota_falhou) → um aviso por nota.
//  - TODO DIA ÚTIL (cron): resumo das notas previstas paradas (pagas, sem serviço feito), das recusadas/com falha ainda
//    sem correção e das paradas em Revisar — a rede de segurança se um aviso na hora se perder.
var et = event.event_type || '';
var papel = String(config.alvo_papel || 'administrador');
function num(v, padrao) {
  return (v === undefined || v === null || v === '') ? padrao : Number(v);
}
var diasPrevista = num(config.dias_parada, 15);
var diasRevisao = num(config.dias_revisao_parada, 2);

function fim(saida, extra) {
  var r = { saida: saida, evento: et || event.origem || '' };
  extra = extra || {};
  for (var k in extra) r[k] = extra[k];
  result(r);
  return r;
}
function brl(n) {
  var s = (Math.round(n * 100) / 100).toFixed(2).split('.');
  return 'R$ ' + s[0].replace(/\B(?=(\d{3})+(?!\d))/g, '.') + ',' + s[1];
}
function avisar(titulo, texto) {
  return call('notificar_grupo', {
    type: 'mensagem', group_id: papel,
    message: { type: 'aviso', title: titulo, text: texto, icon: 'receipt' }
  });
}
function corpo(r) { return (r && r.body) || {}; }

// 1) Na hora: nota recusada ou transmissão parada
if (et === 'financeiro.nota_rejeitada' || et === 'financeiro.nota_falhou') {
  if (config.avisar_na_hora === false) return fim('desligado');
  var ps = event.payload_safe || {};
  var recusa = et === 'financeiro.nota_rejeitada';
  var valor = Number(ps.valor_servico || 0);
  var motivo = String(ps.erro_mensagem || ps.erro_codigo || 'sem detalhe').slice(0, 220);
  var titulo = recusa ? 'Nota fiscal recusada pelo governo' : 'Nota fiscal parada na transmissão';
  var texto = (recusa ? 'A nota de ' + brl(valor) + ' foi recusada: ' : 'A nota de ' + brl(valor) + ' não foi transmitida: ')
    + motivo + (ps.sem_revisao ? ' (saiu sem revisão, pela regra automática)' : '')
    + '. Corrija em Notas fiscais › Corrigir.';
  var a = avisar(titulo, texto);
  return fim('avisou', { tipo: recusa ? 'recusada' : 'falha', ok: a.ok, status: a.status_code, erro: ps.erro_codigo || null });
}

// 2) Resumo diário
if (event.origem === 'cron') {
  var agora = Date.now();
  function lista(status) {
    var r = call('listar_notas', { status: status, origem: '', limit: 500 });
    if (!r.ok) return null;
    return corpo(r).items || [];
  }
  function parada(n, dias) {
    var t = Date.parse(n.updated_at || n.created_at);
    return !isNaN(t) && t < agora - dias * 86400000;
  }
  function soma(ns) { return ns.reduce(function (s, n) { return s + Number(n.valor_servico || 0); }, 0); }

  var previstas = lista('prevista'), recusadas = lista('rejeitada'), falhas = lista('falha'), revisao = lista('revisao_pendente');
  if (previstas === null || recusadas === null || falhas === null || revisao === null) {
    return fim('erro', { etapa: 'listar_notas' });
  }
  previstas = previstas.filter(function (n) { return n.origem === 'agente' && parada(n, diasPrevista); });
  revisao = revisao.filter(function (n) { return parada(n, diasRevisao); });

  var linhas = [];
  if (recusadas.length) linhas.push(recusadas.length + (recusadas.length === 1 ? ' nota recusada' : ' notas recusadas')
    + ' pelo governo (' + brl(soma(recusadas)) + ')');
  if (falhas.length) linhas.push(falhas.length + (falhas.length === 1 ? ' nota com falha' : ' notas com falha')
    + ' na transmissão (' + brl(soma(falhas)) + ')');
  if (revisao.length) linhas.push(revisao.length + (revisao.length === 1 ? ' nota parada' : ' notas paradas')
    + ' em Revisar há mais de ' + diasRevisao + ' dias (' + brl(soma(revisao)) + ')');
  if (previstas.length) linhas.push(previstas.length + (previstas.length === 1 ? ' nota prevista parada' : ' notas previstas paradas')
    + ' há mais de ' + diasPrevista + ' dias (' + brl(soma(previstas)) + '): pagas e sem o serviço feito');
  var conta = { recusadas: recusadas.length, falhas: falhas.length, revisao: revisao.length, previstas: previstas.length };
  if (!linhas.length) return fim('nada_parado', conta);
  var a2 = avisar('Notas fiscais que precisam de alguém', linhas.join('; ') + '. Veja em Notas fiscais.');
  conta.ok = a2.ok;
  conta.status = a2.status_code;
  return fim('avisou', conta);
}
return fim('ignorado', { motivo: 'gatilho desconhecido' });

// Enviador de notas (épico #2268 / #2241) — nota autorizada → e-mail para quem pagou, pela tabela de regras.
// É o MESMO envio do botão (remetente da clínica, limites, registro). O e-mail nunca sai no resultado nem no log.
// O evento tenta na hora; a varredura (a cada 15 min) pega as autorizadas ainda sem envio — a que chegou antes do PDF
// ficar pronto, ou todas, se a clínica ligou "esperar antes de enviar" (aí o evento não envia e a varredura respeita N
// minutos).
var et = event.event_type || '';
var agente = String(context.agente || 'enviador_notas').slice(0, 80);
var esperar = config.esperar_antes === true ? Math.max(1, Number(config.esperar_minutos || 0)) : 0;

function fim(saida, extra) {
  var r = { saida: saida, evento: et || event.origem || '' };
  extra = extra || {};
  for (var k in extra) r[k] = extra[k];
  result(r);
  return r;
}
function corpo(r) { return (r && r.body) || {}; }

// decide e envia UMA nota; devolve a saída (texto curto, sem PII)
function processar(notaId, origem, valor, temEmail) {
  var d = regras.avaliar(config.regras_envio, { origem: origem, tem_email: !!temEmail, valor: valor }, 'regras_envio');
  if (d.saida !== 'enviar') return { saida: d.saida || 'sem_regra', regra: d.linha };
  var info = call('envio_info', { nota_id: notaId });
  if (!info.ok) return { saida: 'erro', etapa: 'envio_info', status: info.status_code, regra: d.linha };
  var i = corpo(info);
  if (!i.pode_enviar) return { saida: 'nao_pode', motivo: String(i.motivo || '').slice(0, 120), regra: d.linha };
  var email = i.destinatario_sugerido && i.destinatario_sugerido.email;
  if (!email) return { saida: 'sem_email', regra: d.linha };
  var r = call('enviar_nota', { nota_id: notaId, destinatario_email: email, incluir_xml: config.incluir_xml !== false });
  return { saida: r.ok ? 'enviada' : 'erro', etapa: r.ok ? undefined : 'enviar', status: r.status_code, regra: d.linha };
}

if (et === 'financeiro.nota_autorizada') {
  if (esperar > 0) return fim('aguardando', { minutos: esperar });
  var sub = event.subject || {}, ps = event.payload_safe || {};
  if (!sub.nota_fiscal_id) return fim('ignorado', { motivo: 'evento sem nota' });
  var res = processar(sub.nota_fiscal_id, ps.origem, Number(ps.valor_servico || 0), ps.tem_email);
  return fim(res.saida, res);
}

if (event.origem === 'cron') {
  // sem espera, 2 min de folga para o PDF; janela de 3 dias (nota mais velha sem envio = decisão de não enviar)
  var agora = Date.now(), limite = agora - Math.max(esperar, 2) * 60000, janela = agora - 3 * 86400000;
  var conta = { candidatas: 0, enviadas: 0, outras: 0 };
  var falhou = null;
  ['agente', 'venda'].forEach(function (origem) {
    var lista = call('listar_notas', { status: 'autorizada', origem: origem, limit: 200 });
    if (!lista.ok) { falhou = lista.status_code; return; }
    (corpo(lista).items || []).forEach(function (n) {
      var t = Date.parse(n.updated_at || n.created_at);
      if (isNaN(t) || t > limite || t < janela || Number(n.envios_total || 0) > 0) return;
      conta.candidatas++;
      var r = processar(n.id, n.origem, Number(n.valor_servico || 0), true);
      if (r.saida === 'enviada') conta.enviadas++; else conta.outras++;
    });
  });
  if (falhou) conta.erro_listar = falhou;
  return fim('varredura', conta);
}
return fim('ignorado', { motivo: 'gatilho desconhecido', agente: agente });
